      "教学目标": "通过动手实验，帮助学生观察液体混合的颜色变化现象，能用简单语言描述实验步骤（如“先加水，再加色素，搅拌”），尝试理解颜色混合的基本原理（如不同颜色液体混合可能产生新颜色），并联系生活场景（如彩虹、颜料）建立初步认知。",
      "教学步骤": [
        {
          "步骤1：引入情境（5分钟）",
          "活动设计": "教师用实物展示一杯混合了红色和蓝色液体的杯子，提问：‘猜猜这杯液体是什么颜色？’引导学生观察并猜测（如‘可能是紫色’‘可能是粉色’），激发探索兴趣。"
        },
        {
          "步骤2：实验操作（15分钟）",
          "活动设计": "分组实验（每组2-3人）：提供材料（塑料杯2个、水200ml、红/蓝/黄食用色素、小棒1根、记录单），要求：\n1. 步骤1：将水倒入第一个杯子，观察初始颜色（透明）；\n2. 步骤2：滴入红色色素，搅拌后观察变化（红色液体）；\n3. 步骤3：滴入蓝色色素，搅拌后观察变化（混合成紫色）；\n4. 步骤4：用记录单画圈记录颜色变化（如‘透明→红色→紫色’）。教师巡回指导，用‘你先做了…然后…’的句式引导描述步骤。"
        },
        {
          "步骤3：总结与联系（5分钟）",
          "活动设计": "教师用PPT展示实验过程图片，提问：‘你们每一步都做了什么？’‘混合后的颜色像什么？’（如‘像彩虹’‘像颜料’），引导学生用‘因为…所以…’简单解释（如‘因为红色和蓝色混合，所以变成紫色’）。"
        }
      ],
      "教学材料": [
        "塑料杯（2个，每组1个）",
        "水（200ml，常温，避免刺激感官）",
        "食用色素（红、蓝、黄，小瓶装，安全无刺激）",
        "小棒（1根，用于搅拌，避免塑料刮伤杯子）",
        "记录单（A4纸打印，画3个圆圈，标注‘步骤1→步骤2→步骤3’，学生用彩笔标记颜色变化）"
      ],
      "教学评估": [
        {
          "观察记录评估": "通过记录单检查学生是否完成‘颜色变化’记录（如‘透明→红色→紫色’），重点关注步骤描述的完整性（如是否包含‘加水’‘滴色素’‘搅拌’）。",
        },
        {
          "口头问答评估": "提问‘你用了哪些材料？’‘混合后颜色怎么变的？’，观察学生是否能用‘先…然后…’描述步骤，是否能说出‘混合颜色’的基本概念（如‘红色+蓝色=紫色’）。",
        {
          "错误纠正": "若学生描述步骤混乱（如‘先滴色素再加水’），用‘你先往杯子里倒水，再滴色素，对吗？’的引导式提问帮助纠正；若对颜色混合原理不理解（如认为‘红色+蓝色=红色’），用‘就像你画画时红色+蓝色=紫色一样，液体混合也会变颜色’类比解释。
        }
      ]
    },
    "extensions": [
      {
        "家庭延伸实验": "鼓励学生在家用不同杯子（如透明杯、玻璃杯）重复实验，观察‘不同杯子装的水量混合后颜色是否变化’（如半杯水和满杯水混合，颜色是否更浅），记录结果并拍照分享给老师。",
      {
        "生活观察任务": "观察厨房中的颜色混合现象（如草莓+酸奶=粉色、牛奶+草莓酱=粉色），用‘颜色混合记录单’（画圆圈记录‘原颜色→混合颜色’）记录，下次课分享。",
      {
        "探索问题引导": "提问‘如果把红色和黄色混合会怎样？’‘如果换成蓝色和红色混合呢？’，鼓励学生用实验验证（提前提供材料），培养‘假设-验证’的科学思维。"
    ]
  }
}

